-- 3. Sync `public.toilet_amenities` for toilets 12..32 so Admin Web `/toilets` displays all amenity badges
INSERT INTO public.toilet_amenities (toilet_id, amenity_id)
SELECT t.toilet_id, a.amenity_id
FROM public.toilets t
CROSS JOIN LATERAL unnest(t.facilities) AS f(facility_name)
JOIN public.amenities a ON a.amenity_name = f.facility_name
WHERE t.toilet_id BETWEEN 12 AND 32
  AND NOT EXISTS (
    SELECT 1
    FROM public.toilet_amenities ta
    WHERE ta.toilet_id = t.toilet_id
      AND ta.amenity_id = a.amenity_id
  );

-- 4. Update sequences for `toilets.toilet_id` and `amenities.amenity_id`
SELECT setval(
  pg_get_serial_sequence('public.toilets', 'toilet_id'),
  (SELECT COALESCE(MAX(toilet_id), 32) FROM public.toilets)
);

SELECT setval(
  pg_get_serial_sequence('public.amenities', 'amenity_id'),
  (SELECT COALESCE(MAX(amenity_id), 6) FROM public.amenities)
);
